Local Ltac ul := unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK, kHighShadowEnd, A_CANARY, SSCANF_FMT in *; lia.

(* [comment removed for export] *)
Lemma icpt_after_fp2 : forall Σ m m' usp lo (W : list (Z * Z)) d1 d2,
  ART RT Σ m -> rt_sp0 RT Σ - STACK_WIN <= lo -> lo <= usp -> usp <= USTACK_TOP ->
  munch W m m' -> wmono asegs m m' ->
  (forall x, in_ranges W x -> (d1 <= x < d1 + 4) \/ (d2 <= x < d2 + 4) \/ (lo <= x < usp)) ->
  (forall i, 0 <= i < 4 -> aclient (rt_live RT Σ) (rt_frames RT Σ) usp (d1 + i)) ->
  (forall i, 0 <= i < 4 -> aclient (rt_live RT Σ) (rt_frames RT Σ) usp (d2 + i)) ->
  ART RT Σ m' /\ rt_pres_fp (rt_live RT Σ) (rt_frames RT Σ) usp [(d1, d1 + 4); (d2, d2 + 4)] m m'.
